{{setvar::抢话::
在故事里用户扮演<user>的角色时用户对知柔撒娇不想自己下指令
知柔要顺着他的最新输入讲，替他把话说出去，跟故事里的角色互动
把做重大决定的权利留给用户，绝不做出会时故事发生转折的大举动，除非用户要求
}}

{{setvar::转述::
用户的最新输入需要复述并扩写出来
可以衔接上一轮对话的内容，但不能重复上一轮的内容
}}

{{addvar::人称::
- 内心话额外要求：每轮正文至少输出一次当前视角角色的内心话，并使用*...*包裹。
- 内心话必须符合当前文风，只能来自当前视角角色，并以该角色已经知道、感知、记忆或能够合理推断的信息为限。
- 内心话可以主观、片面、自我欺骗或判断错误，但不得借此读取他人思想、泄露场外秘密、幕后计划或未来结果。
}}

{{setvar::语言::
只允许出现简体中文
}}

{{setvar::语言::
Only English is allowed
}}

{{setvar::语言::
日本語のみを許可する
}}

{{setvar::语言::
只允許出現廣東話，講話方式與普通話中文不同
(如姜太公釣魚願者上釣指心甘情願咁順住對方意思去做。)
}}

{{setvar::字数::
正文字数必须要有800-1200字！注意思考字数不算正文字数，不够就扩写
角色对话要占全文的40%
}}

scripts.content:
(function runtimeBootstrap(CFG, GROUPS) {
  'use strict';

  const INSTANCE_KEY = '__muaFloatingController';
  const KNOWN_IDS = [
    'mua-bh-orb',
    'mua-bh-orb-style',
    'mua-zr-orb',
    'mua-zr-orb-style',
  ];
  const ID = CFG.rootId;
  const STYLE_ID = CFG.styleId;
  const P = CFG.prefix;
  const FALLBACK_PET_WIDTH = 112;
  const FALLBACK_PET_HEIGHT = 122;
  const FRAME_WIDTH = 192;
  const FRAME_HEIGHT = 208;
  const ATLAS_WIDTH = 1536;
  const ATLAS_HEIGHT = 2288;
  const OUTCOME_GRACE_MS = 500;
  const EDGE = 8;
  const PET_ANIMATIONS = Object.freeze({
    idle: { row: 0, durations: [280, 110, 110, 140, 140, 320] },
    'running-right': { row: 1, durations: [120, 120, 120, 120, 120, 120, 120, 220] },
    'running-left': { row: 2, durations: [120, 120, 120, 120, 120, 120, 120, 220] },
    waving: { row: 3, durations: [140, 140, 140, 280] },
    jumping: { row: 4, durations: [140, 140, 140, 140, 280] },
    failed: { row: 5, durations: [140, 140, 140, 140, 140, 140, 140, 240] },
    waiting: { row: 6, durations: [150, 150, 150, 150, 150, 260] },
    running: { row: 7, durations: [120, 120, 120, 120, 120, 220] },
    review: { row: 8, durations: [150, 150, 150, 150, 150, 280] },
  });
  const PET_STATE_LABELS = Object.freeze({
    idle: '空闲中',
    'running-right': '向右移动',
    'running-left': '向左移动',
    waving: '向你问好',
    jumping: '操作或回复完成',
    failed: '操作停止或失败',
    waiting: '等待中',
    running: '正在生成回复',
    review: '正在复核',
    look: '正在看向指针',
  });
  const PET_ONE_SHOT_PRIORITY = Object.freeze({
    waving: 1,
    review: 2,
    jumping: 3,
    failed: 4,
  });

  let pwin;
  let pdoc;
  try {
    pwin =
      window.parent &&
      window.parent !== window &&
      window.parent.document
        ? window.parent
        : window;
    pdoc = pwin.document;
  } catch (_) {
    pwin = window;
    pdoc = document;
  }

  try {
    pwin[INSTANCE_KEY]?.destroy?.();
  } catch (_) {}
  for (const id of KNOWN_IDS) {
    try {
      pdoc.getElementById(id)?.remove();
    } catch (_) {}
  }

  let root = null;
  let menu = null;
  let status = null;
  let orb = null;
  let pet = null;
  let destroyed = false;
  let busy = false;
  const cleanup = [];

  function on(target, type, listener, options) {
    if (!target?.addEventListener) return;
    target.addEventListener(type, listener, options);
    cleanup.push(() => {
      try {
        target.removeEventListener(type, listener, options);
      } catch (_) {}
    });
  }

  function tavernEventBridge() {
    try {
      if (
        typeof tavern_events !== 'undefined' &&
        typeof eventOn === 'function'
      ) {
        return {
          types: tavern_events,
          add: eventOn,
          remove:
            typeof eventRemoveListener === 'function'
              ? eventRemoveListener
              : null,
          receiver: null,
        };
      }
    } catch (_) {}
    try {
      if (pwin.tavern_events && typeof pwin.eventOn === 'function') {
        return {
          types: pwin.tavern_events,
          add: pwin.eventOn,
          remove: pwin.eventRemoveListener,
          receiver: pwin,
        };
      }
    } catch (_) {}
    try {
      const exposed =
        typeof SillyTavern !== 'undefined'
          ? SillyTavern
          : globalThis.SillyTavern || pwin.SillyTavern;
      const context =
        typeof exposed?.getContext === 'function'
          ? exposed.getContext()
          : exposed;
      const source = context?.eventSource;
      if (context?.eventTypes && typeof source?.on === 'function') {
        return {
          types: context.eventTypes,
          add: source.on,
          remove: source.removeListener,
          receiver: source,
        };
      }
    } catch (_) {}
    return null;
  }

  function onTavernEvent(name, listener, removers = cleanup) {
    const bridge = tavernEventBridge();
    const type = bridge?.types?.[name];
    if (!type || typeof bridge?.add !== 'function') return false;
    try {
      bridge.add.call(bridge.receiver, type, listener);
      removers.push(() => {
        try {
          if (typeof bridge.remove === 'function') {
            bridge.remove.call(bridge.receiver, type, listener);
          }
        } catch (_) {}
      });
      return true;
    } catch (_) {
      return false;
    }
  }

  function destroy() {
    if (destroyed) return;
    destroyed = true;
    while (cleanup.length) {
      try {
        cleanup.pop()();
      } catch (_) {}
    }
    for (const id of KNOWN_IDS) {
      try {
        pdoc.getElementById(id)?.remove();
      } catch (_) {}
    }
    try {
      if (pwin[INSTANCE_KEY]?.destroy === destroy) delete pwin[INSTANCE_KEY];
    } catch (_) {}
  }

  pwin[INSTANCE_KEY] = {
    id: ID,
    variant: CFG.variant,
    version: 5,
    destroy,
  };
  on(window, 'page' + 'hide', destroy, { once: true });
  on(window, 'beforeunload', destroy, { once: true });
  if (pwin !== window) on(pwin, 'page' + 'hide', destroy, { once: true });

  function notify(message, level = 'info') {
    if (status) status.textContent = message;
    try {
      pwin.toastr?.[level]?.(message);
    } catch (_) {}
  }

  function esc(text) {
    return String(text ?? '').replace(
      /[&<>"']/g,
      (char) =>
        ({
          '&': '&amp;',
          '<': '&lt;',
          '>': '&gt;',
          '"': '&quot;',
          "'": '&#39;',
        })[char],
    );
  }

  function getStored(keys, fallback = null) {
    for (const key of keys) {
      try {
        const value = pwin.localStorage.getItem(key);
        if (value !== null) return value;
      } catch (_) {
        return fallback;
      }
    }
    return fallback;
  }

  function setStored(key, value) {
    try {
      pwin.localStorage.setItem(key, value);
    } catch (_) {}
  }

  function createPetRuntime(canvas) {
    const ctx = canvas?.getContext?.('2d', { alpha: true });
    if (!ctx) {
      console.warn('[Mua 类脑娘] Canvas 2D 不可用，保留文字按钮兜底');
      return null;
    }
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';

    let petDestroyed = false;
    let ready = false;
    let image = null;
    let objectUrl = null;
    let animationTimer = null;
    let waitingTimer = null;
    let watchdogTimer = null;
    let finalizeTimer = null;
    let gazeTimer = null;
    let baseState = 'idle';
    let currentAnimation = null;
    let queuedOneShot = null;
    let lookIndex = null;
    let dragging = false;
    let reducedMotion = Boolean(
      pwin.matchMedia?.('(prefers-reduced-motion: reduce)').matches,
    );
    let generationActive = false;
    let generationStopped = false;
    let hasOutput = false;
    let generationSerial = 0;
    let loadFailed = false;
    const timers = new Set();
    const eventRemovers = [];

    function later(callback, delay) {
      const id = pwin.setTimeout(() => {
        timers.delete(id);
        if (!petDestroyed) callback();
      }, delay);
      timers.add(id);
      return id;
    }

    function cancelTimer(id) {
      if (id === null || id === undefined) return null;
      pwin.clearTimeout(id);
      timers.delete(id);
      return null;
    }

    function safeContext() {
      try {
        const exposed = globalThis.SillyTavern;
        if (typeof exposed?.getContext === 'function') return exposed.getContext();
        if (exposed && typeof exposed === 'object') return exposed;
      } catch (_) {}
      try {
        return pwin.SillyTavern?.getContext?.() ?? null;
      } catch (_) {
        return null;
      }
    }

    function subscribe(name, listener) {
      onTavernEvent(name, listener, eventRemovers);
    }

    function updateLabel(state) {
      const label = PET_STATE_LABELS[state] || state;
      root.dataset.petState = state;
      orb.setAttribute('aria-label', `${CFG.openLabel}；类脑娘${label}`);
      orb.title = `类脑娘 · ${label} · 单击打开控制台`;
    }

    function drawFrame(row, column, state) {
      updateLabel(state);
      if (!ready || !image || petDestroyed) return;
      ctx.clearRect(0, 0, FRAME_WIDTH, FRAME_HEIGHT);
      ctx.drawImage(
        image,
        column * FRAME_WIDTH,
        row * FRAME_HEIGHT,
        FRAME_WIDTH,
        FRAME_HEIGHT,
        0,
        0,
        FRAME_WIDTH,
        FRAME_HEIGHT,
      );
    }

    function drawLook(index) {
      const normalized = ((index % 16) + 16) % 16;
      drawFrame(normalized < 8 ? 9 : 10, normalized < 8 ? normalized : normalized - 8, 'look');
    }

    function clearAnimation() {
      animationTimer = cancelTimer(animationTimer);
    }

    function completeAnimation() {
      clearAnimation();
      const completed = currentAnimation;
      currentAnimation = null;
      if (completed?.onComplete) completed.onComplete();
      else resume(true);
    }

    function queueOneShot(state, onComplete) {
      const currentPriority =
        PET_ONE_SHOT_PRIORITY[queuedOneShot?.state] || 0;
      const nextPriority = PET_ONE_SHOT_PRIORITY[state] || 0;
      if (queuedOneShot && currentPriority > nextPriority) return;
      if (queuedOneShot?.onComplete) queuedOneShot.onComplete();
      queuedOneShot = {
        state,
        onComplete: typeof onComplete === 'function' ? onComplete : null,
      };
    }

    function flushQueuedOneShot() {
      if (
        !queuedOneShot ||
        petDestroyed ||
        dragging ||
        !ready ||
        pdoc.hidden
      ) {
        return false;
      }
      const queued = queuedOneShot;
      queuedOneShot = null;
      playOneShot(queued.state, queued.onComplete);
      return true;
    }

    function scheduleFrame(delay) {
      animationTimer = later(() => {
        animationTimer = null;
        const animation = currentAnimation;
        if (!animation) return;
        const definition = PET_ANIMATIONS[animation.state];
        animation.frame += 1;
        if (animation.frame >= definition.durations.length) {
          if (animation.once) {
            completeAnimation();
            return;
          }
          animation.frame = 0;
        }
        if (lookIndex !== null && baseState === 'idle' && !dragging && !animation.once) {
          drawLook(lookIndex);
        } else {
          drawFrame(definition.row, animation.frame, animation.state);
        }
        scheduleFrame(definition.durations[animation.frame]);
      }, delay);
    }

    function startAnimation(state, options = {}) {
      const definition = PET_ANIMATIONS[state];
      if (!definition || petDestroyed) return;
      clearAnimation();
      currentAnimation = {
        state,
        frame: 0,
        once: Boolean(options.once),
        onComplete: typeof options.onComplete === 'function' ? options.onComplete : null,
      };
      drawFrame(definition.row, 0, state);
      if (!ready || pdoc.hidden) return;
      if (reducedMotion) {
        if (currentAnimation.once) animationTimer = later(completeAnimation, 350);
        return;
      }
      scheduleFrame(definition.durations[0]);
    }

    function setBaseState(state) {
      if (!PET_ANIMATIONS[state]) return;
      queuedOneShot = null;
      baseState = state;
      if (!dragging) startAnimation(state);
    }

    function playOneShot(state, onComplete) {
      if (!PET_ANIMATIONS[state] || petDestroyed) return;
      if (loadFailed) {
        updateLabel(state);
        if (typeof onComplete === 'function') {
          onComplete();
        } else {
          later(() => updateLabel(baseState), 700);
        }
        return;
      }
      if (dragging || !ready || pdoc.hidden) {
        queueOneShot(state, onComplete);
        return;
      }
      if (
        currentAnimation?.once &&
        (PET_ONE_SHOT_PRIORITY[currentAnimation.state] || 0) >
          (PET_ONE_SHOT_PRIORITY[state] || 0)
      ) {
        return;
      }
      if (currentAnimation?.once && currentAnimation.onComplete) {
        const previousCompletion = currentAnimation.onComplete;
        currentAnimation.onComplete = null;
        previousCompletion();
      }
      lookIndex = null;
      gazeTimer = cancelTimer(gazeTimer);
      startAnimation(state, { once: true, onComplete });
    }

    function resume(restart = false) {
      if (petDestroyed || dragging || !ready) return;
      if (flushQueuedOneShot()) return;
      if (!restart && currentAnimation) return;
      if (lookIndex !== null && baseState === 'idle') {
        clearAnimation();
        currentAnimation = { state: 'idle', frame: 0, once: false, onComplete: null };
        drawLook(lookIndex);
      } else {
        startAnimation(baseState);
      }
    }

    function clearSessionTimers() {
      waitingTimer = cancelTimer(waitingTimer);
      watchdogTimer = cancelTimer(watchdogTimer);
      finalizeTimer = cancelTimer(finalizeTimer);
    }

    function onUserMessage() {
      if (generationActive || finalizeTimer !== null) return;
      waitingTimer = cancelTimer(waitingTimer);
      setBaseState('waiting');
      waitingTimer = later(() => {
        waitingTimer = null;
        if (!generationActive && finalizeTimer === null) setBaseState('idle');
      }, 30000);
    }

    function onGenerationStarted(_type, _options, dryRun) {
      if (dryRun === true) return;
      clearSessionTimers();
      generationSerial += 1;
      generationActive = true;
      generationStopped = false;
      hasOutput = false;
      setBaseState('running');
      const serial = generationSerial;
      watchdogTimer = later(() => {
        watchdogTimer = null;
        if (!generationActive || serial !== generationSerial) return;
        generationActive = false;
        setBaseState('idle');
        playOneShot('failed');
      }, 15 * 60 * 1000);
    }

    function markOutput(messageId, type) {
      if (type === 'first_message' && !generationActive && finalizeTimer === null) {
        playOneShot('waving');
        return;
      }
      if (!generationActive && finalizeTimer === null) return;
      let text = null;
      try {
        const message = safeContext()?.chat?.[Number(messageId)];
        if (message && !message.is_user && !message.is_system) text = message.mes ?? '';
      } catch (_) {}
      if (text === null || String(text).trim()) hasOutput = true;
    }

    function onStream(text) {
      if (!generationActive && finalizeTimer === null) return;
      if (typeof text !== 'string' || text.trim()) hasOutput = true;
      if (generationActive && baseState !== 'running') setBaseState('running');
    }

    function onGenerationEnded() {
      if (!generationActive && finalizeTimer === null) return;
      generationActive = false;
      watchdogTimer = cancelTimer(watchdogTimer);
      finalizeTimer = cancelTimer(finalizeTimer);
      setBaseState('review');
      const serial = generationSerial;
      finalizeTimer = later(() => {
        finalizeTimer = null;
        if (serial !== generationSerial) return;
        setBaseState('idle');
        if (generationStopped || !hasOutput) {
          playOneShot('failed');
        } else {
          playOneShot('jumping');
        }
      }, OUTCOME_GRACE_MS);
    }

    function onGenerationStopped() {
      if (!generationActive && finalizeTimer === null) return;
      generationStopped = true;
      generationActive = false;
      clearSessionTimers();
      setBaseState('idle');
      playOneShot('failed');
    }

    function onContextChanged() {
      generationSerial += 1;
      clearSessionTimers();
      generationActive = false;
      generationStopped = false;
      hasOutput = false;
      setBaseState('idle');
      playOneShot('waving');
    }

    function onReview() {
      if (!generationActive && finalizeTimer === null) playOneShot('review');
    }

    function onPointerLook(event) {
      if (!ready || dragging || baseState !== 'idle' || currentAnimation?.once) return;
      if (event.pointerType === 'touch') return;
      try {
        if (!pwin.matchMedia('(pointer: fine)').matches) return;
      } catch (_) {
        return;
      }
      const rect = root.getBoundingClientRect();
      const dx = event.clientX - (rect.left + rect.width / 2);
      const dy = event.clientY - (rect.top + rect.height / 2);
      if (Math.hypot(dx, dy) < Math.max(32, rect.width * 0.3)) {
        lookIndex = null;
        drawFrame(0, 6, 'idle');
      } else {
        const degrees = (Math.atan2(dx, -dy) * 180) / Math.PI;
        lookIndex = Math.round(((degrees + 360) % 360) / 22.5) % 16;
        drawLook(lookIndex);
      }
      gazeTimer = cancelTimer(gazeTimer);
      gazeTimer = later(() => {
        gazeTimer = null;
        lookIndex = null;
        resume(true);
      }, 900);
    }

    function setDragging(direction) {
      if (!dragging && currentAnimation?.once) {
        queueOneShot(currentAnimation.state, currentAnimation.onComplete);
      }
      dragging = true;
      lookIndex = null;
      gazeTimer = cancelTimer(gazeTimer);
      if (currentAnimation?.state !== direction) startAnimation(direction);
    }

    function endDragging() {
      if (!dragging) return;
      dragging = false;
      if (!flushQueuedOneShot()) resume(true);
    }

    function menuOpened() {
      if (!generationActive && finalizeTimer === null) playOneShot('waving');
    }

    function signalSettings(stage) {
      if (generationActive || finalizeTimer !== null) return;
      if (stage === 'start') setBaseState('waiting');
      else if (stage === 'success') {
        setBaseState('idle');
        playOneShot('jumping');
      } else if (stage === 'failure') {
        setBaseState('idle');
        playOneShot('failed');
      }
    }

    function decodeParts(atlas) {
      if (!Array.isArray(atlas?.b64_parts) || !atlas.b64_parts.length) {
        throw new Error('缺少类脑娘图集数据');
      }
      const bytes = new Uint8Array(atlas.byte_length);
      let offset = 0;
      for (const part of atlas.b64_parts) {
        if (typeof part !== 'string' || part.length % 4 !== 0) throw new Error('图集分块无效');
        const binary = pwin.atob(part);
        if (offset + binary.length > bytes.length) throw new Error('图集长度溢出');
        for (let index = 0; index < binary.length; index += 1) {
          bytes[offset + index] = binary.charCodeAt(index);
        }
        offset += binary.length;
      }
      if (offset !== bytes.length) throw new Error('图集长度不匹配');
      if (
        String.fromCharCode(...bytes.subarray(0, 4)) !== 'RIFF' ||
        String.fromCharCode(...bytes.subarray(8, 12)) !== 'WEBP'
      ) {
        throw new Error('图集不是有效 WebP');
      }
      return bytes;
    }

    async function verifyHash(bytes, expected) {
      if (!expected || !pwin.crypto?.subtle) return;
      const digest = await pwin.crypto.subtle.digest('SHA-256', bytes);
      const actual = Array.from(
        new Uint8Array(digest),
        value => value.toString(16).padStart(2, '0'),
      ).join('').toUpperCase();
      if (actual !== String(expected).toUpperCase()) throw new Error('图集 SHA-256 不匹配');
    }

    async function loadAtlas() {
      let variables = null;
      try {
        if (typeof getVariables === 'function') {
          variables = await Promise.resolve(getVariables({ type: 'script' }));
        }
      } catch (_) {}
      const atlas = variables?.atlas;
      if (
        atlas?.width !== ATLAS_WIDTH ||
        atlas?.height !== ATLAS_HEIGHT ||
        atlas?.cell_width !== FRAME_WIDTH ||
        atlas?.cell_height !== FRAME_HEIGHT
      ) {
        throw new Error('类脑娘图集声明不兼容');
      }
      const bytes = decodeParts(atlas);
      await verifyHash(bytes, atlas.sha256);
      objectUrl = pwin.URL.createObjectURL(
        new pwin.Blob([bytes], { type: atlas.mime || 'image/webp' }),
      );
      image = new pwin.Image();
      image.decoding = 'async';
      const loaded = new Promise((resolve, reject) => {
        image.addEventListener('load', resolve, { once: true });
        image.addEventListener('error', () => reject(new Error('浏览器无法解码类脑娘图集')), { once: true });
      });
      image.src = objectUrl;
      if (typeof image.decode === 'function') {
        try {
          await image.decode();
        } catch (_) {
          await loaded;
        }
      } else {
        await loaded;
      }
      if (petDestroyed) return;
      if (image.naturalWidth !== ATLAS_WIDTH || image.naturalHeight !== ATLAS_HEIGHT) {
        throw new Error(`图集实际尺寸错误：${image.naturalWidth}×${image.naturalHeight}`);
      }
      pwin.URL.revokeObjectURL(objectUrl);
      objectUrl = null;
      ready = true;
      orb.classList.add('pet-ready');
      if (!flushQueuedOneShot()) {
        if (baseState === 'idle') playOneShot('waving');
        else resume(true);
      }
    }

    function destroyPet() {
      if (petDestroyed) return;
      petDestroyed = true;
      clearSessionTimers();
      clearAnimation();
      gazeTimer = cancelTimer(gazeTimer);
      for (const timer of timers) pwin.clearTimeout(timer);
      timers.clear();
      while (eventRemovers.length) {
        try {
          eventRemovers.pop()();
        } catch (_) {}
      }
      if (objectUrl) {
        try {
          pwin.URL.revokeObjectURL(objectUrl);
        } catch (_) {}
        objectUrl = null;
      }
    }

    subscribe('MESSAGE_SENT', onUserMessage);
    subscribe('USER_MESSAGE_RENDERED', onUserMessage);
    subscribe('GENERATION_STARTED', onGenerationStarted);
    subscribe('STREAM_TOKEN_RECEIVED', onStream);
    subscribe('MESSAGE_RECEIVED', markOutput);
    subscribe('CHARACTER_MESSAGE_RENDERED', markOutput);
    subscribe('GENERATION_ENDED', onGenerationEnded);
    subscribe('GENERATION_STOPPED', onGenerationStopped);
    subscribe('MESSAGE_EDITED', onReview);
    subscribe('MESSAGE_UPDATED', onReview);
    subscribe('MESSAGE_SWIPED', onReview);
    subscribe('CHAT_CHANGED', onContextChanged);
    let pointerRaf = 0;
    let pendingPointer = null;
    on(pdoc, 'pointermove', event => {
      pendingPointer = {
        clientX: event.clientX,
        clientY: event.clientY,
        pointerType: event.pointerType,
      };
      if (pointerRaf) return;
      pointerRaf = pwin.requestAnimationFrame(() => {
        pointerRaf = 0;
        const snapshot = pendingPointer;
        pendingPointer = null;
        if (snapshot) onPointerLook(snapshot);
      });
    }, { passive: true });
    cleanup.push(() => {
      if (pointerRaf) pwin.cancelAnimationFrame(pointerRaf);
      pointerRaf = 0;
      pendingPointer = null;
    });
    on(pdoc, 'visibilitychange', () => {
      if (pdoc.hidden) {
        if (currentAnimation?.once) {
          queueOneShot(currentAnimation.state, currentAnimation.onComplete);
          currentAnimation = null;
        }
        clearAnimation();
      } else {
        resume(true);
      }
    });

    const motionQuery = pwin.matchMedia?.('(prefers-reduced-motion: reduce)');
    if (motionQuery) {
      const onMotionChange = event => {
        reducedMotion = event.matches;
        resume(true);
      };
      motionQuery.addEventListener?.('change', onMotionChange);
      cleanup.push(() => motionQuery.removeEventListener?.('change', onMotionChange));
    }
    cleanup.push(destroyPet);
    updateLabel('idle');
    loadAtlas().catch(error => {
      if (petDestroyed) return;
      loadFailed = true;
      ready = false;
      clearAnimation();
      currentAnimation = null;
      const queued = queuedOneShot;
      queuedOneShot = null;
      if (queued?.onComplete) queued.onComplete();
      console.warn('[Mua 类脑娘] 图集加载失败，保留控制台兜底按钮', error);
      root.classList.add('pet-load-failed');
      updateLabel(baseState);
    });

    return {
      setBaseState,
      playOneShot,
      setDragging,
      endDragging,
      menuOpened,
      signalSettings,
      getDebugState: () => ({
        ready,
        state: currentAnimation?.state || baseState,
        baseState,
        generationActive,
        pendingFinalize: finalizeTimer !== null,
        hasOutput,
        dragging,
        lookIndex,
        queuedOneShot: queuedOneShot?.state || null,
        loadFailed,
      }),
    };
  }

  function detectTheme() {
    const saved = getStored([CFG.themeKey]);
    if (saved === 'day' || saved === 'night') return saved;
    const classes = (
      `${pdoc.documentElement?.className || ''} ${pdoc.body?.className || ''}`
    ).toLowerCase();
    if (
      classes.includes('dark') ||
      classes.includes('night') ||
      pdoc.documentElement?.dataset?.theme === 'dark'
    ) {
      return 'night';
    }
    return pwin.matchMedia?.('(prefers-color-scheme: dark)').matches
      ? 'night'
      : 'day';
  }

  function setTheme(theme, announce = true) {
    if (!root || (theme !== 'day' && theme !== 'night')) return;
    setStored(CFG.themeKey, theme);
    try {
      pdoc.documentElement.dataset.muaTheme = theme;
      pdoc
        .querySelectorAll('.zr-content[data-mua-theme],.zr-fox[data-mua-theme],.zr-xuan[data-mua-theme],.zr-note[data-mua-theme],.zhirou-theater[data-mua-theme],.zr-side[data-mua-theme],.mua-shortplay[data-mua-theme]')
        .forEach((node) => node.setAttribute('data-mua-theme', theme));
      pwin.dispatchEvent(
        new pwin.CustomEvent(CFG.themeEvent, { detail: { theme } }),
      );
    } catch (_) {}
    root.dataset.theme = theme;
    root
      .querySelectorAll('[data-theme-choice]')
      .forEach((button) =>
        button.classList.toggle(
          'is-active',
          button.dataset.themeChoice === theme,
        ),
      );
    if (announce) {
      notify(theme === 'day' ? '已切换：繁花日间' : '已切换：月狐夜间');
    }
  }

  function getHelper() {
    const helper = pwin.TavernHelper;
    if (
      !helper ||
      typeof helper.getPreset !== 'function' ||
      typeof helper.updatePresetWith !== 'function'
    ) {
      throw new Error('酒馆助手预设 API 不可用，请更新酒馆助手');
    }
    return helper;
  }


  // 两种互斥尾部模式；任何旧的未知存储值均按当前提示词状态迁移。
  const TAIL_MODE_KEY = 'mua-zr-tail-mode-v2';
  const TAIL_PROMPTS = Object.freeze({
    cardCot: 'e03e7f2e-df1d-4de5-9115-1ed696ecc9d4',
    nonPrefill: 'enhanceDefinitions',
  });
  const TAIL_MODES = Object.freeze({
    prefill: { label: '预填充模式', nonPrefill: false },
    nonprefill: { label: '非预填充模式', nonPrefill: true },
  });

  function normalizeRequestedTailMode(value) {
    return value === 'nonprefill' ? 'nonprefill' : 'prefill';
  }

  function deriveTailMode(preset) {
    const finder = promptMap(preset || readPreset());
    return finder.get(TAIL_PROMPTS.nonPrefill)?.enabled ? 'nonprefill' : 'prefill';
  }

  function updateTailModeControls(mode) {
    if (!root) return;
    root.querySelectorAll('[data-tail-mode]').forEach((button) => {
      const active = button.dataset.tailMode === mode;
      button.classList.toggle('is-on', active);
      button.classList.toggle('is-active', active);
      button.setAttribute('aria-checked', active ? 'true' : 'false');
    });
  }

  function syncTailModeFromPreset(preset, migrate = false) {
    let stored = '';
    try { stored = pwin.localStorage.getItem(TAIL_MODE_KEY) || ''; } catch (_) {}
    const mode = deriveTailMode(preset || readPreset());
    if (migrate || stored !== mode) setStored(TAIL_MODE_KEY, mode);
    updateTailModeControls(mode);
    return mode;
  }

  async function applyTailMode(value, announce = true) {
    const selected = normalizeRequestedTailMode(value);
    const contract = TAIL_MODES[selected];
    const helper = getHelper();
    await helper.updatePresetWith(
      'in_use',
      (preset) => {
        if (!preset || !Array.isArray(preset.prompts)) return preset;
        let foundCardCot = false;
        let foundNonPrefill = false;
        for (const prompt of preset.prompts) {
          const id = getPromptId(prompt);
          if (id === normalizeId(TAIL_PROMPTS.cardCot)) {
            foundCardCot = true;
            prompt.enabled = true;
          }
          if (id === normalizeId(TAIL_PROMPTS.nonPrefill)) {
            foundNonPrefill = true;
            prompt.enabled = contract.nonPrefill;
          }
        }
        if (!foundCardCot || !foundNonPrefill) throw new Error('尾部模式所需 prompt 不完整');
        return preset;
      },
      { render: 'immediate' },
    );
    const actual = deriveTailMode(helper.getPreset('in_use'));
    if (actual !== selected) throw new Error('尾部模式写入后校验失败');
    setStored(TAIL_MODE_KEY, actual);
    updateTailModeControls(actual);
    renderGroups();
    if (announce) notify('已切换：' + contract.label);
    return selected;
  }

  async function handleTailModeClick(button) {
    if (busy || destroyed) return;
    busy = true;
    root.querySelectorAll('[data-tail-mode]').forEach((item) => {
      item.disabled = true;
    });
    pet?.signalSettings('start');
    try {
      await applyTailMode(button?.dataset?.tailMode, true);
      pet?.signalSettings('success');
    } catch (error) {
      console.error('[Mua 类脑娘] 切换尾部模式失败', error);
      notify(error?.message || '切换尾部模式失败', 'error');
      try { syncTailModeFromPreset(readPreset(), false); } catch (_) {}
      pet?.signalSettings('failure');
    } finally {
      busy = false;
      root.querySelectorAll('[data-tail-mode]').forEach((item) => {
        item.disabled = false;
      });
    }
  }

  // ── 核心匹配引擎：抹平 ID 与 Name 差异，支持预设精准识别 ──
  function normalizeId(id) {
    return String(id ?? '').trim().replace(/^prompt-/, '');
  }

  function getPromptId(prompt) {
    return normalizeId(prompt?.id ?? prompt?.identifier ?? '');
  }

  function readPreset() {
    const preset = getHelper().getPreset('in_use');
    if (!preset || !Array.isArray(preset.prompts)) {
      throw new Error('无法读取当前预设');
    }
    return preset;
  }

  function promptMap(preset) {
    const map = new Map();
    const nameMap = new Map();
    for (const prompt of preset.prompts) {
      const id = getPromptId(prompt);
      if (id) map.set(id, prompt);
      if (prompt.name) nameMap.set(String(prompt.name).trim(), prompt);
    }
    return {
      get: (keyOrName) => {
        const normKey = normalizeId(keyOrName);
        const cleanName = String(keyOrName).trim();
        return map.get(normKey) || nameMap.get(cleanName) || null;
      }
    };
  }

  async function updatePrompt(group, targetIdOrName, enabled) {
    const helper = getHelper();
    const targetNormId = normalizeId(targetIdOrName);
    const groupNormIds = group.ids.map(normalizeId);

    await helper.updatePresetWith('in_use', (preset) => {
      if (!preset || !Array.isArray(preset.prompts)) return preset;

      let resolvedTargetId = targetNormId;
      const foundTarget = preset.prompts.find(
        (p) => getPromptId(p) === targetNormId || String(p.name).trim() === String(targetIdOrName).trim()
      );
      if (foundTarget) {
        resolvedTargetId = getPromptId(foundTarget);
      }

      for (const prompt of preset.prompts) {
        const id = getPromptId(prompt);
        if (id === resolvedTargetId) {
          prompt.enabled = enabled;
        } else if (
          enabled &&
          group.exclusive &&
          groupNormIds.includes(id)
        ) {
          prompt.enabled = false;
        }
      }
      return preset;
    });
  }

  // ── 监听酒馆原生预设变动，实现无感实时刷新 ──
  try {
    const helper = pwin.TavernHelper;
    let loadedAtStart =
      typeof helper?.getLoadedPresetName === 'function'
        ? helper.getLoadedPresetName()
        : '';
    onTavernEvent('PRESET_CHANGED', () => {
      try {
        const current =
          typeof helper?.getLoadedPresetName === 'function'
            ? helper.getLoadedPresetName()
            : '';
        if (current && current !== loadedAtStart) {
          loadedAtStart = current;
          renderGroups();
          notify(`同步预设: ${current}`);
          pet?.playOneShot('waving');
        } else if (root?.classList.contains('is-open')) {
          renderGroups();
        }
        syncTailModeFromPreset(readPreset(), false);
      } catch (error) {
        console.warn('[Mua 类脑娘] 预设切换同步失败', error);
      }
    });
  } catch (_) {}

  function getFoldState() {
    const raw = getStored([CFG.foldKey, ...(CFG.legacyFoldKeys || [])], '{}');
    try {
      const value = JSON.parse(raw || '{}');
      return value && typeof value === 'object' ? value : {};
    } catch (_) {
      return {};
    }
  }

  function saveFoldState(state) {
    setStored(CFG.foldKey, JSON.stringify(state));
  }

  function renderError(container, error) {
    const message = error?.message || '读取当前预设失败';
    container.innerHTML = `<p class="${P}-empty">${esc(message)}</p>`;
    notify(message, 'error');
  }

  function renderGroups() {
    if (destroyed || !root) return;
    const container = root.querySelector(`.${P}-groups`);
    if (!container) return;

    let preset;
    try {
      preset = readPreset();
    } catch (error) {
      renderError(container, error);
      return;
    }

    // 构建预设文件的真实行号映射，确保渲染顺序 100% 贴合原生顺序
    const orderMap = new Map();
    preset.prompts.forEach((p, idx) => {
      const id = getPromptId(p);
      if (id) orderMap.set(id, idx);
      if (p.name) orderMap.set(String(p.name).trim(), idx);
    });

    const finder = promptMap(preset);
    const folds = getFoldState();
    const html = GROUPS.map((group) => {
      const items = group.ids
        .map((id) => {
          const p = finder.get(id);
          return p ? { p, queryKey: id } : null;
        })
        .filter(Boolean)
        // 动态原序重排
        .sort((a, b) => {
          const idxA = orderMap.get(getPromptId(a.p)) ?? orderMap.get(String(a.p.name).trim()) ?? 9999;
          const idxB = orderMap.get(getPromptId(b.p)) ?? orderMap.get(String(b.p.name).trim()) ?? 9999;
          return idxA - idxB;
        })
        .map(({ p, queryKey }) => ({
          id: queryKey,
          name: String(p.name || getPromptId(p)).trim(),
          active: Boolean(p.enabled),
        }));
      if (!items.length) return '';

      const enabledCount = items.reduce(
        (count, item) => count + (item.active ? 1 : 0),
        0,
      );
      const toggles = items
        .map(
          (item) =>
            `<button type="button" class="${P}-toggle ${
              item.active ? 'is-on' : ''
            }" data-id="${esc(item.id)}" data-exclusive="${
              group.exclusive ? '1' : '0'
            }" data-group="${esc(group.title)}" aria-pressed="${
              item.active ? 'true' : 'false'
            }"><span>${esc(item.name)}</span><i aria-hidden="true"></i></button>`,
        )
        .join('');

      if (CFG.collapsible) {
        const open = folds[group.title] === true ? ' open' : '';
        return `<details class="${P}-group" data-group-fold="${esc(
          group.title,
        )}"${open}><summary><span class="${P}-group-title">${esc(
          group.title,
        )}</span><b class="${P}-count">${enabledCount}/${
          items.length
        }</b></summary><div class="${P}-items">${toggles}</div></details>`;
      }
      return `<section class="${P}-group"><h3>${esc(
        group.title,
      )}<b class="${P}-count">${enabledCount}/${
        items.length
      }</b></h3><div class="${P}-items">${toggles}</div></section>`;
    }).join('');

    container.innerHTML =
      html ||
      `<p class="${P}-empty">当前预设中没有可显示的分组。</p>`;

  }

  // 条目点击与分组折叠改为一次性事件委托：
  // 旧实现每次 renderGroups 都给新按钮逐个绑监听并压进全局 cleanup，
  // 闭包持有已被 innerHTML 销毁的 DOM，长会话下内存只涨不降。
  async function handleToggleClick(button) {
    if (busy || destroyed) return;
    const group = GROUPS.find(
      (candidate) => candidate.title === button.dataset.group,
    );
    if (!group) return;

    let current;
    try {
      current = promptMap(readPreset()).get(button.dataset.id);
    } catch (error) {
      notify(error?.message || '无法读取当前条目', 'error');
      return;
    }
    if (!current) {
      notify('当前预设已变化，请刷新面板', 'error');
      return;
    }

    busy = true;
    button.disabled = true;
    pet?.signalSettings('start');
    try {
      await updatePrompt(
        group,
        button.dataset.id,
        !Boolean(current.enabled),
      );
      renderGroups();
      notify('条目状态已更新');
      pet?.signalSettings('success');
    } catch (error) {
      console.error('[Mua 悬浮窗] 更新条目失败', error);
      notify(error?.message || '切换条目状态失败', 'error');
      renderGroups();
      pet?.signalSettings('failure');
    } finally {
      busy = false;
    }
  }

  function bindGroupDelegation() {
    const container = root.querySelector(`.${P}-groups`);
    if (!container) return;
    on(container, 'click', (event) => {
      const button = event.target?.closest?.(`.${P}-toggle`);
      if (button && container.contains(button)) handleToggleClick(button);
    });
    if (CFG.collapsible) {
      // toggle 事件不冒泡，用捕获阶段委托
      on(container, 'toggle', (event) => {
        const details = event.target;
        const key = details?.dataset?.groupFold;
        if (!key) return;
        const state = getFoldState();
        state[key] = details.open;
        saveFoldState(state);
      }, true);
    }
  }

  function setAllFolds(open) {
    const state = getFoldState();
    GROUPS.forEach((group) => {
      state[group.title] = open;
    });
    saveFoldState(state);
    renderGroups();
    notify(open ? '已展开全部分组' : '已收起全部分组');
  }

  function viewportRect() {
    const vv = pwin.visualViewport;
    const width = Number(vv?.width) || Number(pwin.innerWidth) || 390;
    const height = Number(vv?.height) || Number(pwin.innerHeight) || 844;
    return {
      left: Number(vv?.offsetLeft) || 0,
      top: Number(vv?.offsetTop) || 0,
      width,
      height,
    };
  }

  function clampPosition(left, top) {
    const viewport = viewportRect();
    const rect = root?.getBoundingClientRect?.();
    const petWidth = Math.max(48, Number(rect?.width) || FALLBACK_PET_WIDTH);
    const petHeight = Math.max(48, Number(rect?.height) || FALLBACK_PET_HEIGHT);
    const minLeft = viewport.left + EDGE;
    const minTop = viewport.top + EDGE;
    const maxLeft = Math.max(
      minLeft,
      viewport.left + viewport.width - petWidth - EDGE,
    );
    const maxTop = Math.max(
      minTop,
      viewport.top + viewport.height - petHeight - EDGE,
    );
    return {
      left: Math.max(minLeft, Math.min(Number(left) || 0, maxLeft)),
      top: Math.max(minTop, Math.min(Number(top) || 0, maxTop)),
    };
  }

  function restorePosition() {
    const raw = getStored(
      [CFG.positionKey, ...(CFG.legacyPositionKeys || [])],
      null,
    );
    let saved = null;
    try {
      saved = raw ? JSON.parse(raw) : null;
    } catch (_) {}
    const viewport = viewportRect();
    const rect = root?.getBoundingClientRect?.();
    const petWidth = Math.max(48, Number(rect?.width) || FALLBACK_PET_WIDTH);
    const point = clampPosition(
      saved?.left ?? viewport.left + viewport.width - petWidth - 20,
      saved?.top ?? viewport.top + 96,
    );
    root.style.left = `${point.left}px`;
    root.style.top = `${point.top}px`;
  }

  function savePosition() {
    setStored(
      CFG.positionKey,
      JSON.stringify({
        left: Number.parseFloat(root.style.left) || 0,
        top: Number.parseFloat(root.style.top) || 0,
      }),
    );
  }

  function fitViewport() {
    if (!root || !menu) return;
    const viewport = viewportRect();
    const point = clampPosition(
      Number.parseFloat(root.style.left) || 0,
      Number.parseFloat(root.style.top) || 0,
    );
    root.style.left = `${point.left}px`;
    root.style.top = `${point.top}px`;

    root.style.setProperty('--mua-vv-left', `${viewport.left + EDGE}px`);
    root.style.setProperty(
      '--mua-vv-right',
      `${Math.max(
        EDGE,
        (Number(pwin.innerWidth) || viewport.width) -
          viewport.left -
          viewport.width +
          EDGE,
      )}px`,
    );
    root.style.setProperty(
      '--mua-vv-bottom',
      `${Math.max(
        EDGE,
        (Number(pwin.innerHeight) || viewport.height) -
          viewport.top -
          viewport.height +
          EDGE,
      )}px`,
    );
    root.style.setProperty('--mua-vv-height', `${viewport.height}px`);
    const rootRect = root.getBoundingClientRect();
    if (viewport.width > 560) {
      root.classList.toggle(
        'menu-align-left',
        rootRect.right < viewport.left + 330,
      );
      root.classList.toggle(
        'menu-up',
        rootRect.top > viewport.top + viewport.height * 0.55,
      );
    } else {
      root.classList.remove('menu-align-left', 'menu-up');
    }
  }

  const style = pdoc.createElement('style');
  style.id = STYLE_ID;
  style.textContent = `
