  // fitViewport 用 rAF 节流：visualViewport 的 scroll/resize 在手机上会连续高频触发
  let fitRaf = 0;
  function fitViewportThrottled() {
    if (fitRaf) return;
    fitRaf = pwin.requestAnimationFrame(() => {
      fitRaf = 0;
