@media (prefers-reduced-motion:reduce){
  :is(.zr-content,.zr-fox,.zr-xuan,.zr-note,.zhirou-theater,.zr-side,.mua-shortplay) *,
  :is(.zr-content,.zr-fox,.zr-xuan,.zr-note,.zhirou-theater,.zr-side,.mua-shortplay) *::before,
