}`;

  let pwin;
  let pdoc;
  try {
    pwin =
      window.parent &&
      window.parent !== window &&
      window.parent.document
        ? window.parent
        : window;
    pdoc = pwin.document;
  } catch (_) {
    pwin = window;
    pdoc = document;
  }

  try {
    pwin[INSTANCE_KEY]?.destroy?.();
  } catch (_) {}

  let destroyed = false;
  let theme = 'night';
  let generationActive = false;
  let dirtyDuringGeneration = false;
  let renderTimer = 0;
  let renderRaf = 0;
  let rendering = false;
  const observedFrames = new Map();
  const boundDocuments = new WeakSet();
  const styledDocuments = new Set();
  const warnedComponents = new Set();
  const cleanup = [];

  function make(doc, tag, className, text) {
    const node = doc.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function moveChildren(source, target) {
    while (source.firstChild) target.appendChild(source.firstChild);
  }

  function summaryLine(doc, className, titleClass, title, star = '✦') {
    const summary = make(doc, 'summary', className);
    summary.append(
      make(doc, 'span', className.startsWith('zt-') ? 'zt-icon' : className.startsWith('zs-') ? 'zs-star' : 'zr-fire', star),
      make(doc, 'span', className.startsWith('zt-') ? 'zt-line' : className.startsWith('zs-') ? 'zs-line' : 'zr-line'),
      make(doc, 'span', titleClass, title),
      make(doc, 'span', className.startsWith('zt-') ? 'zt-line' : className.startsWith('zs-') ? 'zs-line' : 'zr-line'),
      make(doc, 'span', className.startsWith('zt-') ? 'zt-icon' : className.startsWith('zs-') ? 'zs-star' : 'zr-fire', star),
    );
    return summary;
  }

  function replaceSource(source, rendered) {
    rendered.classList.add('mua-zr-component');
    rendered.dataset.muaRendered = '1';
    source.replaceWith(rendered);
  }

  function renderContent(source) {
    const doc = source.ownerDocument;
    const root = make(doc, 'section', 'zr-content');
    const card = make(doc, 'div', 'zr-content-card');
    const particles = make(doc, 'div', 'zr-particles');
    particles.setAttribute('aria-hidden', 'true');
    for (let index = 1; index <= 5; index += 1) {
      particles.appendChild(make(doc, 'span', `zr-particle zr-p${index}`));
    }
    const head = make(doc, 'div', 'zr-content-head');
    head.append(
      make(doc, 'span', 'zr-content-fire', '✦'),
      make(doc, 'span', 'zr-content-line'),
      make(doc, 'span', 'zr-content-title', '知柔执笔'),
      make(doc, 'span', 'zr-content-line'),
      make(doc, 'span', 'zr-content-fire', '✦'),
    );
    const body = make(doc, 'div', 'zr-content-body');
    moveChildren(source, body);
    card.append(
      particles,
      head,
      body,
      make(doc, 'div', 'zr-content-tail', '灯火未歇'),
    );
    root.appendChild(card);
    replaceSource(source, root);
  }

  function renderThinking(source) {
    const doc = source.ownerDocument;
    const raw = String(source.innerText || source.textContent || '').trim();
    const root = make(doc, 'details', 'zr-fox');
    root.appendChild(summaryLine(doc, 'zr-head', 'zr-title', '知柔耳语中..'));
    const body = make(doc, 'div', 'zr-body');
    const list = make(doc, 'div', 'zr-list');
    const lines = raw.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
    if (!lines.length) {
      list.appendChild(make(doc, 'div', 'zr-empty', '狐火暂熄'));
    } else {
      lines.forEach((line, index) => {
        const match = line.match(/^【([^】]+)】\s*([\s\S]*)$/);
        const item = make(doc, 'div', 'zr-item');
        item.style.animationDelay = `${index * 0.045}s`;
        item.append(
          make(
            doc,
            'span',
            'zr-tag',
            match ? `【${match[1].trim()}】` : `【狐思${String(index + 1).padStart(2, '0')}】`,
          ),
          make(doc, 'span', 'zr-text', match ? match[2].trim() : line),
        );
        list.appendChild(item);
      });
    }
    body.appendChild(list);
    root.appendChild(body);
    replaceSource(source, root);
  }

  function renderNote(source) {
    const doc = source.ownerDocument;
    const root = make(doc, 'details', 'zr-note');
    const summary = make(doc, 'summary', 'zr-note-summary');
    summary.append(
      make(doc, 'span', 'zr-note-star', '✦'),
      make(doc, 'span', 'zr-note-line'),
      doc.createTextNode('知柔记载中'),
      make(doc, 'span', 'zr-note-line'),
      make(doc, 'span', 'zr-note-star', '✦'),
    );
    const content = make(doc, 'div', 'zr-note-content');
    moveChildren(source, content);
    root.append(summary, content);
    replaceSource(source, root);
  }

  function renderZhirouSays(source) {
    const doc = source.ownerDocument;
    const root = make(doc, 'details', 'zhirou-theater');
    root.appendChild(summaryLine(doc, 'zt-head', 'zt-title', '知柔的幕后碎碎念', '✧'));
    const body = make(doc, 'div', 'zt-body');
    const content = make(doc, 'div', 'zt-content');
    moveChildren(source, content);
    body.appendChild(content);
    root.appendChild(body);
    replaceSource(source, root);
  }

  function renderSideStory(source) {
    const doc = source.ownerDocument;
    const root = make(doc, 'details', 'zr-side');
    root.appendChild(summaryLine(doc, 'zs-head', 'zs-title', '知柔支线故事'));
    const body = make(doc, 'div', 'zs-body');
    const content = make(doc, 'div', 'zs-content');
    moveChildren(source, content);
    body.appendChild(content);
    root.appendChild(body);
    replaceSource(source, root);
  }

  function renderShortplay(source) {
    const doc = source.ownerDocument;
    const root = make(doc, 'details', 'mua-shortplay mua-shortplay-auto');
    const summary = make(doc, 'summary');
    summary.append(
      make(doc, 'span', 'msp-curtain'),
      make(doc, 'span', 'msp-orb'),
      make(doc, 'span', 'msp-title', '知 柔 · 幕 间 小 剧 场'),
      make(doc, 'span', 'msp-chevron', '⌄'),
    );
    summary.querySelector('.msp-orb').setAttribute('aria-hidden', 'true');
    summary.querySelector('.msp-chevron').setAttribute('aria-hidden', 'true');
    const stage = make(doc, 'div', 'msp-stage');
    const output = make(doc, 'div', 'msp-output');
    moveChildren(source, output);
    stage.append(make(doc, 'div', 'msp-label', '幕间同步 · 非正文'), output);
    root.append(summary, stage);
    replaceSource(source, root);
  }

  function parseChoices(source) {
    const text = String(source.innerText || source.textContent || '').trim();
    const choices = [];
    for (const line of text.split(/\r?\n/)) {
      const match = line.trim().match(/^([A-D])[.、:：]\s*(?:\(\s*\$\s*)?(.+?)(?:\s*\))?\s*$/i);
      if (match) choices.push({ key: match[1].toUpperCase(), text: match[2].trim() });
    }
    if (choices.length >= 2) return choices;
    choices.length = 0;
    const compact = /([A-D])[.、:：]\s*(?:\(\s*\$\s*)?([\s\S]*?)(?=\s+[A-D][.、:：]|$)/gi;
    let match;
    while ((match = compact.exec(text))) {
      const value = match[2].replace(/\s*\)\s*$/, '').trim();
      if (value) choices.push({ key: match[1].toUpperCase(), text: value });
    }
    return choices;
  }

  function fitChoiceWidth(root) {
    if (!root?.isConnected) return;
    const doc = root.ownerDocument;
    const host =
      root.closest('.mes_text,.message_text,[data-message-text],.mes_block') ||
      root.parentElement;
    const parent = root.parentElement;
    if (!host || !parent || host === root) return;
    try {
      root.style.position = 'relative';
      root.style.left = '0px';
      root.style.removeProperty('margin-left');
      root.style.removeProperty('margin-right');
      root.style.setProperty('width', '100%', 'important');
      const hostRect = host.getBoundingClientRect();
      const naturalRect = root.getBoundingClientRect();
      const style = doc.defaultView?.getComputedStyle(host);
      const borderLeft = Number.parseFloat(style?.borderLeftWidth || '0') || 0;
      const borderRight = Number.parseFloat(style?.borderRightWidth || '0') || 0;
      const targetLeft = hostRect.left + borderLeft;
      const targetRight = hostRect.right - borderRight;
      const leftBleed = Math.max(0, naturalRect.left - targetLeft);
      const rightBleed = Math.max(0, targetRight - naturalRect.right);
      const totalBleed = leftBleed + rightBleed;
      if (totalBleed > 0) {
        root.style.marginLeft = `${-leftBleed}px`;
        root.style.marginRight = `${-rightBleed}px`;
        root.style.setProperty(
          'width',
          `calc(100% + ${totalBleed}px)`,
          'important',
        );
        root.style.setProperty('max-width', 'none', 'important');
      } else {
        root.style.removeProperty('max-width');
      }
    } catch (_) {}
  }

  function renderChoices(source) {
    const doc = source.ownerDocument;
    const choices = parseChoices(source);
    const root = make(doc, 'div', 'zr-xuan');
    if (!choices.length) {
      const fallback = make(doc, 'div', 'zr-xuan-text');
      moveChildren(source, fallback);
      root.appendChild(fallback);
    } else {
      for (const choice of choices) {
        const button = make(doc, 'button', 'zr-xuan-btn');
        button.type = 'button';
        button.dataset.muaChoice = choice.text;
        button.append(
          make(doc, 'span', 'zr-xuan-key', choice.key),
          make(doc, 'span', 'zr-xuan-text', choice.text),
        );
        root.appendChild(button);
      }
    }
    replaceSource(source, root);
    fitChoiceWidth(root);
  }

  function findComposer() {
    const selectors = ['#send_textarea', 'textarea#send_textarea', 'textarea[name="user_input"]', '#chat-input textarea'];
    const windows = [pwin];
    try {
      for (const frame of pdoc.querySelectorAll('iframe')) {
        if (frame.contentWindow) windows.push(frame.contentWindow);
      }
    } catch (_) {}
    for (const targetWindow of windows) {
      try {
        for (const selector of selectors) {
          const input = targetWindow.document?.querySelector(selector);
          if (input && !input.closest?.('[data-mua-rendered]')) return { input, targetWindow };
        }
      } catch (_) {}
    }
    return null;
  }

  function insertChoice(text) {
    const found = findComposer();
    if (!found || !text) return;
    const { input, targetWindow } = found;
    const previous = String(input.value || '');
    const next = previous.trim() ? `${previous.replace(/\s*$/, '')}\n${text}` : text;
    try {
      const proto =
        input.tagName === 'TEXTAREA'
          ? targetWindow.HTMLTextAreaElement.prototype
          : targetWindow.HTMLInputElement.prototype;
      const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
      if (setter) setter.call(input, next);
      else input.value = next;
    } catch (_) {
      input.value = next;
    }
    input.dispatchEvent(new targetWindow.Event('input', { bubbles: true }));
    input.dispatchEvent(new targetWindow.Event('change', { bubbles: true }));
    input.focus();
  }

  function bindDocument(doc) {
    if (!doc || boundDocuments.has(doc)) return;
    boundDocuments.add(doc);
    const onClick = (event) => {
      const button = event.target?.closest?.('[data-mua-choice]');
      if (!button) return;
      event.preventDefault();
      insertChoice(String(button.dataset.muaChoice || '').trim());
    };
    doc.addEventListener('click', onClick);
    cleanup.push(() => {
      try {
        doc.removeEventListener('click', onClick);
      } catch (_) {}
    });
  }

  function renderDocument(doc, completedOnly = false) {
    if (!doc?.querySelectorAll) return;
    bindDocument(doc);
    const selector = '[data-mua-component]';
    const sources = Array.from(doc.querySelectorAll(selector));
    for (const source of sources) {
      if (
        !source.isConnected ||
        source.closest('script,style,textarea,template,.mua-zr-component')
      ) {
        continue;
      }
      const component = source.dataset.muaComponent;
      try {
        switch (component) {
          case 'zhirou_thinking': renderThinking(source); break;
          case 'content': renderContent(source); break;
          case 'xuan': renderChoices(source); break;
          case 'note': renderNote(source); break;
          case 'zhiroushuo': renderZhirouSays(source); break;
          case 'zhirou_side_story': renderSideStory(source); break;
          case 'zhirou_shortplay': renderShortplay(source); break;
          default: throw new Error('未知组件：' + component);
        }
      } catch (error) {
        const key = component || 'unknown';
        if (!warnedComponents.has(key)) {
          warnedComponents.add(key);
          console.warn('[Mua 至柔美化] 组件渲染失败：' + key, error);
        }
      }
    }
  }

  function detectTheme() {
    try {
      const saved = pwin.localStorage.getItem(THEME_KEY);
      if (saved === 'day' || saved === 'night') return saved;
    } catch (_) {}
    try {
      const hostTheme = pdoc.documentElement?.dataset?.muaTheme;
      if (hostTheme === 'day' || hostTheme === 'night') return hostTheme;
    } catch (_) {}
    try {
      return pwin.matchMedia?.('(prefers-color-scheme: light)').matches
        ? 'day'
        : 'night';
    } catch (_) {
      return 'night';
    }
